
/* el analisis ahora muestra el video del robot estudiando el partido */
const ANVIDW="data:video/webm;base64,";
const ANVID="data:video/mp4;base64,";
stageHTML=function(g){const ms=t=>(typeof MS==="function"?MS(t):"");return `<div class="scan"><div class="shdr"><span>ANALIZANDO EN TIEMPO REAL</span><span class="lv">● LIVE</span></div>
 <div class="vbox"><video id="anv" autoplay muted loop playsinline preload="auto" aria-label="El robot de TOUCH IQ analiza el partido"><source src="${ANVIDW}" type="video/webm"><source src="${ANVID}" type="video/mp4"></video>
 <div class="vside"><div class="vtm"><div>${ms(g.h)}<b>${g.h}</b></div><span>VS</span><div style="text-align:right">${ms(g.a)}<b>${g.a}</b></div></div>
 <div class="prog"><i id="pg"></i></div><div id="log"></div><button id="skip">SALTAR ▸</button></div></div></div>`};
openGame=function(k){OPEN=k;const g=getG(k);TMR.forEach(clearTimeout);TMR=[];$("ov").classList.remove("hide");$("ov").scrollTop=0;document.body.style.overflow="hidden";
 $("stage").classList.remove("hide");$("res").classList.add("hide");$("stage").innerHTML=stageHTML(g);simStart(g);
 const v=$("anv");if(v){v.muted=true;const p=v.play&&v.play();if(p&&p.catch)p.catch(()=>{})}
 const L=lines(g),step=Math.max(420,Math.round(7200/Math.max(1,L.length)));
 L.forEach((t,i)=>TMR.push(setTimeout(()=>{const d=document.createElement("div");d.className="ll"+(i==L.length-1?" ok":"");d.textContent=(i==L.length-1?"✔ ":"▸ ")+t;$("log").appendChild(d);$("pg").style.width=((i+1)/L.length*100)+"%"},i*step+250)));
 TMR.push(setTimeout(()=>showRes(1),L.length*step+700))};
